// Fixture runner. repeat runs the same material again so a replay vector can
// expect the second result. Ed25519 and ES256 tokens are generated by tests.

import { readFileSync } from "node:fs";
import { evidenceSchema, type Evidence } from "./schema.ts";
import type { EvidenceStore } from "./store.ts";
import { verifierFor, type VerifierDeps } from "./verifier.ts";

export interface VectorFile {
  version: number;
  vectors: Vector[];
}

export interface Vector {
  name: string;
  source: string;
  now: string;
  material: Record<string, unknown>;
  expect: Record<string, string>;
  repeat?: number;
  jwks?: unknown;
}

export function loadVectors(path: string): Vector[] {
  const document = JSON.parse(readFileSync(path, "utf8")) as VectorFile;
  if (document.version !== 1 || !Array.isArray(document.vectors)) {
    throw new Error("vector file must be version 1 with a vectors array");
  }
  return document.vectors;
}

export async function runVector(vector: Vector, store: EvidenceStore, deps: VerifierDeps = {}): Promise<Evidence[]> {
  const count = vector.repeat ?? 1;
  if (!Number.isInteger(count) || count < 1) throw new Error("repeat must be a positive integer");
  const verifier = verifierFor(vector.source, store, deps);
  const now = new Date(`${vector.now.replace("Z", "")}Z`);
  const results: Evidence[] = [];
  for (let index = 0; index < count; index += 1) {
    results.push(evidenceSchema.parse(await verifier.verify(vector.material, now)));
  }
  return results;
}
